104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        LocalDate registrationDate = BusinessDay.adjust(
108	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
109	        owner.setRegistrationDate(registrationDate);
110	        Collection<Owner> owners = this.clinicService.findAllOwners();
111	        if (owners.stream().filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() >= 100) {
112	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
113	        }
114	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
115	        if (owners.stream().anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()))
116	                || (!sharesHousehold && owners.stream().anyMatch(existing -> sameHousehold(existing, owner)))
117	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setNamesakeCount((int) owners.stream()
121	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
122	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
123	            .count());
124	        owner.setHouseholdMemberCount(1 + (int) owners.stream().filter(existing -> sameHousehold(existing, owner)).count());
125	        owner.setCustomerCode(CustomerCode.of(owner, owners));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        ownerDto.setBulkSignupWarning(owners.stream()
129	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() > 80);
130	        headers.setLocation(UriComponentsBuilder.newInstance()
131	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
132	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
133	    }
134	
135	    /** Two owners share a household when their last name and address match, compared
136	     *  case-insensitively with runs of whitespace collapsed to a single space. */
137	    private static boolean sameHousehold(Owner a, Owner b) {
138	        return a.getLastName().equalsIgnoreCase(b.getLastName())
139	            && a.getAddress().trim().replaceAll("\\s+", " ")
140	                .equalsIgnoreCase(b.getAddress().trim().replaceAll("\\s+", " "));
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")

