20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "namesake_count")
62	    private Integer namesakeCount;
63	
64	    @Column(name = "household_member_count")
65	    private Integer householdMemberCount;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    /** Default an absent registration date to the server's current date on first persist. */
71	    @PrePersist
72	    void defaultRegistrationDate() {
73	        if (this.registrationDate == null) {
74	            this.registrationDate = LocalDate.now();
75	        }
76	    }
77	
78	    public LocalDate getRegistrationDate() {
79	        return this.registrationDate;
80	    }
81	
82	    public void setRegistrationDate(LocalDate registrationDate) {
83	        this.registrationDate = registrationDate;
84	    }
85	
86	    public String getCustomerCode() {
87	        return this.customerCode;
88	    }
89	
90	    /** Stable identifier shared by owners of the same household (matching last name and address). */
91	    @Transient
92	    public String getHouseholdId() {
93	        return HouseholdId.of(getLastName(), this.address);
94	    }
95	
96	    public void setCustomerCode(String customerCode) {
97	        this.customerCode = customerCode;
98	    }
99	
100	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
101	    @Transient
102	    public String getMembershipNumber() {
103	        return MembershipNumber.of(this.customerCode, this.registrationDate);
104	    }
105	
106	    public Integer getNamesakeCount() {
107	        return this.namesakeCount;
108	    }
109	
110	    public void setNamesakeCount(Integer namesakeCount) {
111	        this.namesakeCount = namesakeCount;
112	    }
113	
114	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
115	     *  captured when the owner was created, including this owner. */
116	    public Integer getHouseholdMemberCount() {
117	        return this.householdMemberCount;
118	    }
119	
120	    public void setHouseholdMemberCount(Integer householdMemberCount) {
121	        this.householdMemberCount = householdMemberCount;
122	    }
123	
124	    public String getEmail() {
125	        return this.email;
126	    }
127	
128	    public void setEmail(String email) {
129	        this.email = email == null ? null : email.toLowerCase();
130	    }
131	
132	    public String getAddress() {
133	        return this.address;
134	    }
135	
136	    public void setAddress(String address) {
137	        this.address = AddressNormalizer.normalize(address);
138	    }
139	
140	    public String getCity() {
141	        return this.city;
142	    }
143	
144	    public void setCity(String city) {
145	        this.city = city;
146	    }
147	
148	    public String getTelephone() {
149	        return this.telephone;
150	    }
151	
152	    public void setTelephone(String telephone) {
153	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
154	    }
155	
156	    protected Set<Pet> getPetsInternal() {
157	        if (this.pets == null) {
158	            this.pets = new HashSet<>();
159	        }
160	        return this.pets;
161	    }
162	
163	    protected void setPetsInternal(Set<Pet> pets) {
164	        this.pets = pets;
165	    }
166	
167	    public List<Pet> getPets() {
168	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
169	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
170	        return Collections.unmodifiableList(sortedPets);
171	    }
172	
173	    public void setPets(List<Pet> pets) {
174	        this.pets = new HashSet<>(pets);
175	    }
176	
177	    public void addPet(Pet pet) {
178	        getPetsInternal().add(pet);
179	        pet.setOwner(this);
180	    }
181	
182	    /**
183	     * Return the Pet with the given name, or null if none found for this Owner.
184	     *
185	     * @param name to test
186	     * @return true if pet name is already in use
187	     */
188	    public Pet getPet(String name) {
189	        return getPet(name, false);
190	    }
