135	    /** Two owners share a household when their last name and address match, compared
136	     *  case-insensitively with runs of whitespace collapsed to a single space. */
137	    private static boolean sameHousehold(Owner a, Owner b) {
138	        return a.getLastName().equalsIgnoreCase(b.getLastName())
139	            && a.getAddress().trim().replaceAll("\\s+", " ")
140	                .equalsIgnoreCase(b.getAddress().trim().replaceAll("\\s+", " "));
141	    }
