151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
